    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 45-year-old woman presents with a slow-growing, painless mass in the right lateral neck. Palpation of the mass elicits a "shooting" electrical sensation radiating down her right arm. What is the most likely diagnosis?', '["Branchial cleft cyst", "Metastatic squamous cell carcinoma", "Schwannoma (neurilemmoma)", "Carotid body tumor", "Lipoma"]'::jsonb, 2, 'A schwannoma is a benign nerve sheath tumor. Tapping or palpating the mass often elicits a "shooting" electrical pain along the distribution of the involved nerve, a clinical finding known as Tinel''s sign.'),
    (v_topic_id, 'A neck MRI of a patient with a suspected schwannoma shows a well-circumscribed, encapsulated mass along the path of the brachial plexus. A biopsy is obtained. What are the pathognomonic histologic features of a schwannoma?', '["Small round blue cells forming rosettes", "Alternating dense cellular areas (Antoni A) with Verocay bodies, and loose myxoid areas (Antoni B)", "Spindle cells with nuclear palisading but no true capsule (neurofibroma)", "Zymogen granules", "Clear cells with abundant glycogen"]'::jsonb, 1, 'The classic histologic appearance of a schwannoma is a biphasic pattern consisting of highly cellular Antoni A areas (which contain palisading nuclei forming Verocay bodies) and hypocellular, myxoid Antoni B areas.'),
    (v_topic_id, 'A 30-year-old man presents with bilateral vestibular schwannomas (acoustic neuromas), multiple meningiomas, and a strong family history of similar tumors. What is the diagnosis?', '["Neurofibromatosis type 1 (NF-1)", "Neurofibromatosis type 2 (NF-2)", "Multiple Endocrine Neoplasia type 2A (MEN 2A)", "Gorlin syndrome", "von Hippel-Lindau disease"]'::jsonb, 1, 'Bilateral vestibular schwannomas are the hallmark of Neurofibromatosis type 2 (NF-2), an autosomal dominant condition caused by a mutation in the Merlin (NF2) tumor suppressor gene on chromosome 22.'),
    (v_topic_id, 'Unlike a schwannoma, which can often be carefully dissected free from the underlying nerve fibers, what is the anatomical relationship of a neurofibroma to its parent nerve?', '["It grows exclusively outside the epineurium", "It completely destroys the nerve, leaving no fibers behind", "It is intimately intermixed with the nerve fibers, making it impossible to resect the tumor without sacrificing the nerve", "It is attached only by a small vascular pedicle", "It arises from the myelin sheath and easily slides off"]'::jsonb, 2, 'Neurofibromas are unencapsulated and grow infiltratively among the axons. Therefore, complete resection of a neurofibroma inevitably requires resection of the involved nerve segment.'),
    (v_topic_id, 'A patient with Neurofibromatosis type 1 (NF-1) develops a rapidly enlarging, painful mass in a previously stable plexiform neurofibroma. What is the most likely and devastating complication?', '["Hemorrhage into the tumor", "Malignant transformation into a Malignant Peripheral Nerve Sheath Tumor (MPNST)", "Infection of the tumor", "Development of a synchronous squamous cell carcinoma", "Rupture of the tumor"]'::jsonb, 1, 'Patients with NF-1 have a significant lifetime risk (approximately 8-10%) of a plexiform neurofibroma undergoing malignant transformation into an MPNST, which is a highly aggressive sarcoma with a very poor prognosis.'),
    (v_topic_id, 'Which of the following describes the most common clinical presentation of a basal cell carcinoma (BCC) on the sun-exposed face?', '["A rapidly growing, painful, black nodule", "A scaly, erythematous patch that bleeds easily", "A slow-growing, pearly or translucent papule with rolled borders and arborizing telangiectasias", "A soft, movable, subcutaneous mass", "A firm, dome-shaped nodule with a central keratin-filled crater"]'::jsonb, 2, 'The nodular subtype of basal cell carcinoma classically presents as a pearly, somewhat translucent papule or nodule, often with a central depression or ulceration, rolled edges, and prominent surface telangiectasias.'),
    (v_topic_id, 'What is the primary biological difference between Basal Cell Carcinoma (BCC) and Squamous Cell Carcinoma (SCC) of the head and neck skin regarding their metastatic potential?', '["BCC metastasizes frequently to regional nodes, while SCC rarely does", "Both have an equally high rate of metastasis", "BCC almost never metastasizes (rate <0.1%), whereas SCC has a significant potential for both regional and distant metastasis", "BCC spreads hematogenously, while SCC spreads lymphatically", "Both never metastasize"]'::jsonb, 2, 'BCC is locally destructive (sometimes called a "rodent ulcer") and can invade deep structures if neglected, but it exceedingly rarely metastasizes. Cutaneous SCC, however, can aggressively metastasize to regional lymph nodes, especially from high-risk areas like the ear or lip.'),
    (v_topic_id, 'A 75-year-old farmer presents with a 2-cm, ulcerated, crusted lesion firmly attached to the cartilage of the superior helix of his right ear. Biopsy confirms invasive squamous cell carcinoma. Why is cutaneous SCC of the ear considered "high-risk"?', '["It is resistant to radiation therapy", "The skin is very thin, allowing early invasion into the underlying perichondrium/cartilage, and it has a higher rate of metastasis (10-15%) compared to SCC on other sun-exposed areas", "It always occurs bilaterally", "It is highly contagious", "It is usually a misdiagnosed melanoma"]'::jsonb, 1, 'SCC of the ear (and lip) is notorious for early deep invasion and a significantly higher rate of regional nodal metastasis (typically to the parotid or level II nodes) compared to SCC on the extremities or trunk.'),
    (v_topic_id, 'What is the preferred surgical technique for removing a high-risk basal cell or squamous cell carcinoma in cosmetically sensitive and anatomically complex areas of the face (e.g., the nose, eyelid, or lip) to ensure complete removal while preserving maximal normal tissue?', '["Wide local excision with a 2-cm margin", "Cryotherapy", "Mohs micrographic surgery", "Electrodessication and curettage", "Topical 5-fluorouracil"]'::jsonb, 2, 'Mohs surgery involves serial excision of the tumor with 100% margin evaluation under a microscope while the patient is in the office. It offers the highest cure rate and spares the maximum amount of healthy tissue in cosmetically vital areas.'),
    (v_topic_id, 'A 50-year-old man has a 1.2-mm deep malignant melanoma excised from his left cheek. His clinical neck examination is negative. What is the standard next step to accurately stage the regional lymph nodes?', '["Observation only", "Empiric radiation to the neck", "Elective radical neck dissection", "Sentinel lymph node biopsy (SLNB)", "Systemic chemotherapy"]'::jsonb, 3, 'For melanomas with a Breslow depth between 0.8 mm and 4.0 mm (or thinner with high-risk features like ulceration), a Sentinel Lymph Node Biopsy is standard of care to identify clinically occult regional metastasis and guide further therapy.'),
    (v_topic_id, 'In performing a Sentinel Lymph Node Biopsy for a melanoma of the anterior scalp, the radioactive tracer maps to a lymph node entirely within the substance of the parotid gland. What is the appropriate surgical procedure to safely retrieve this sentinel node?', '["Enucleation of the node alone through a small stab incision", "Superficial parotidectomy with facial nerve dissection", "Core needle biopsy of the parotid", "Observation", "Total parotidectomy with facial nerve sacrifice"]'::jsonb, 1, 'Because "plucking" a lymph node out of the parotid gland blindly carries a high risk of injuring the facial nerve, the standard and safe approach is to perform a formal superficial parotidectomy, dissecting the facial nerve to safely remove the node-bearing tissue.'),
    (v_topic_id, 'A patient undergoes a massive composite resection for an advanced oral cavity cancer, resulting in a large defect of the lateral mandible and the overlying skin of the cheek. What is the optimal reconstructive option to restore both the bone and the soft tissue?', '["A pectoralis major myocutaneous regional flap", "A split-thickness skin graft", "A free fibula osteocutaneous flap", "A titanium reconstruction plate covered by a local rotation flap", "A radial forearm free flap"]'::jsonb, 2, 'The free fibula osteocutaneous flap is the gold standard for reconstructing large composite mandibular defects. It provides a long segment of strong cortical bone that can be shaped with osteotomies and an overlying skin paddle for soft tissue coverage.'),
    (v_topic_id, 'What is the primary advantage of the radial forearm free flap in head and neck reconstruction?', '["It provides a large volume of bone", "It provides thin, pliable, and highly vascularized hairless skin, ideal for reconstructing mucosal defects in the oral cavity or pharynx", "It provides a massive amount of bulk to fill large dead spaces", "It has the lowest donor site morbidity of any flap", "It does not require microvascular anastomosis"]'::jsonb, 1, 'The radial forearm free flap is the workhorse for soft tissue reconstruction in the head and neck. Its thinness and pliability allow the surgeon to precisely recreate complex three-dimensional mucosal surfaces, such as the tongue or floor of the mouth, without adding excessive bulk.'),
    (v_topic_id, 'If a massive soft tissue defect (e.g., following a total glossectomy) requires a large volume of bulky tissue for reconstruction, which free flap is most commonly utilized?', '["Radial forearm free flap", "Free fibula flap", "Anterolateral thigh (ALT) free flap", "Split-thickness skin graft", "Latissimus dorsi free flap"]'::jsonb, 2, 'The Anterolateral Thigh (ALT) flap can be harvested with a large amount of vastus lateralis muscle and subcutaneous fat, making it an excellent choice when significant bulk is needed to obliterate a dead space or reconstruct a massive soft-tissue defect. It also has very low donor-site morbidity.'),
    (v_topic_id, 'Before the advent of microvascular free flaps, what was the primary "workhorse" pedicled regional flap used for major head and neck soft tissue reconstruction, and is still widely used today as a salvage option?', '["The deltopectoral flap", "The pectoralis major myocutaneous flap", "The latissimus dorsi pedicled flap", "The trapezius flap", "The supraclavicular artery island flap"]'::jsonb, 1, 'The pectoralis major flap is a robust, reliable, and bulky pedicled flap based on the thoracoacromial artery. It can be easily rotated into the neck or lower face and is invaluable in salvage situations or in patients who are not candidates for prolonged free flap surgery.'),
    (v_topic_id, 'A patient with advanced (Stage IV) squamous cell carcinoma of the oropharynx is planned for definitive concurrent chemoradiation. Which chemotherapeutic agent is the standard radiosensitizer used in this setting?', '["Paclitaxel", "5-Fluorouracil (5-FU)", "Cisplatin", "Methotrexate", "Doxorubicin"]'::jsonb, 2, 'High-dose Cisplatin (usually given every 3 weeks) is the gold standard concurrent chemotherapeutic agent used with radiation therapy for squamous cell carcinoma of the head and neck, as it potently sensitizes the tumor cells to the radiation.'),
    (v_topic_id, 'What is the most significant dose-limiting toxicity of Cisplatin that requires aggressive preventative management (e.g., massive intravenous hydration) during its administration?', '["Cardiotoxicity", "Hepatotoxicity", "Nephrotoxicity", "Pulmonary fibrosis", "Alopecia"]'::jsonb, 2, 'Cisplatin is highly nephrotoxic and can cause acute kidney injury. Patients must receive aggressive pre- and post-infusion intravenous hydration and frequent monitoring of their renal function. It is also highly ototoxic and neurotoxic.'),
    (v_topic_id, 'In a patient whose renal function is too poor to tolerate Cisplatin, which targeted biologic agent is often substituted concurrently with radiation therapy for head and neck squamous cell carcinoma?', '["Bevacizumab (anti-VEGF)", "Cetuximab (anti-EGFR)", "Rituximab (anti-CD20)", "Trastuzumab (anti-HER2)", "Imatinib (anti-BCR-ABL)"]'::jsonb, 1, 'Cetuximab is a monoclonal antibody targeting the Epidermal Growth Factor Receptor (EGFR), which is overexpressed in over 90% of head and neck SCCs. It is FDA-approved for use with radiation in patients who cannot tolerate platinum-based chemotherapy.'),
    (v_topic_id, 'What is a classic, visible side effect of Cetuximab therapy that interestingly correlates with a better tumor response?', '["Severe alopecia", "A severe acneiform (papulopustular) skin rash on the face and upper torso", "Jaundice", "Gingival hyperplasia", "Petechiae"]'::jsonb, 1, 'The acneiform rash is a hallmark of EGFR inhibitors. Studies have shown that the severity of the rash directly correlates with improved overall survival and response to the drug.'),
    (v_topic_id, 'A 65-year-old man who underwent definitive radiation therapy for tonsil cancer 5 years ago presents with severe pain in his jaw, foul-smelling breath, and an area of exposed, dead bone in his mandible. What is this devastating late complication of radiation therapy called?', '["Osteomyelitis", "Osteoradionecrosis (ORN)", "Bisphosphonate-related osteonecrosis of the jaw (BRONJ)", "Recurrent squamous cell carcinoma", "Fibrous dysplasia"]'::jsonb, 1, 'Osteoradionecrosis is a severe, late complication caused by radiation-induced endarteritis obliterans (destruction of the microvasculature). The bone becomes hypovascular, hypocellular, and hypoxic, rendering it unable to heal from even minor trauma (like a tooth extraction), leading to necrosis and exposure.'),
    (v_topic_id, 'What is the most critical preventative measure that must be completed BEFORE a patient begins radiation therapy to the oral cavity or oropharynx to minimize the risk of Osteoradionecrosis?', '["Prophylactic antibiotics", "A thorough dental evaluation with extraction of any unsalvageable or severely diseased teeth", "Hyperbaric oxygen therapy", "Placement of a feeding tube", "Tracheostomy"]'::jsonb, 1, 'Dental extractions should be performed prior to radiation, and the gums allowed to heal. Extracting teeth from an already irradiated mandible is the most common trigger for catastrophic osteoradionecrosis.'),
    (v_topic_id, 'If a patient develops severe, refractory Osteoradionecrosis of the mandible that fails conservative management (antibiotics, hyperbaric oxygen, minor debridement), what is the definitive surgical treatment?', '["Repeated curettage", "Long-term intravenous antibiotics only", "Segmental mandibulectomy (resecting the dead bone) with vascularized free flap reconstruction (e.g., free fibula flap)", "Application of bone morphogenetic protein", "Radiation to the opposite side"]'::jsonb, 2, 'Because the surrounding tissue is profoundly ischemic from the radiation, non-vascularized bone grafts will fail. The only way to cure severe ORN is to cut back to healthy, bleeding bone and bring in new, fully vascularized tissue via a free flap.'),
    (v_topic_id, 'Which salivary glands are most susceptible to permanent damage from radiation therapy, leading to severe, lifelong xerostomia (dry mouth)?', '["The submandibular glands", "The sublingual glands", "The minor salivary glands", "The parotid glands", "They are all equally susceptible"]'::jsonb, 3, 'The serous acinar cells of the parotid glands are exquisitely sensitive to radiation. Even moderate doses can cause irreversible damage, resulting in thick, ropy saliva or complete xerostomia, which drastically impairs swallowing and increases dental caries.'),
    (v_topic_id, 'Which radioprotectant drug, acting as a free-radical scavenger, is sometimes administered intravenously prior to daily radiation fractions to specifically reduce the incidence and severity of xerostomia?', '["Pilocarpine", "Cevimeline", "Amifostine", "Bethanechol", "Atropine"]'::jsonb, 2, 'Amifostine is an organic thiophosphate that acts as a cytoprotective agent by scavenging free radicals. It is FDA-approved to reduce the incidence of moderate-to-severe xerostomia in patients undergoing postoperative radiation for head and neck cancer.'),
    (v_topic_id, 'Following radiation therapy to the neck, patients are at a significantly increased risk for developing strictures in which of the following anatomic structures?', '["The trachea", "The carotid artery", "The internal jugular vein", "The upper esophageal sphincter and cervical esophagus", "The Eustachian tube"]'::jsonb, 3, 'Radiation-induced fibrosis commonly leads to severe narrowing (strictures) of the pharynx and upper esophagus, causing profound dysphagia that often requires repeated endoscopic dilations or the permanent use of a gastrostomy tube.'),
    (v_topic_id, 'A patient treated with radiation therapy to the neck 15 years ago presents with a transient ischemic attack (TIA). What radiation-induced vascular complication must be suspected?', '["Carotid artery blowout", "Carotid body tumor", "Accelerated atherosclerosis and severe stenosis of the carotid artery", "Internal jugular vein thrombosis", "Aneurysm of the external carotid artery"]'::jsonb, 2, 'Radiation to the neck causes chronic endothelial injury and dramatically accelerates atherosclerosis in the carotid arteries, significantly increasing the risk of high-grade stenosis, TIA, and stroke decades after treatment.'),
    (v_topic_id, 'What is the most feared and rapidly fatal complication that can occur in a patient with a massive, ulcerated neck recurrence or severe wound breakdown following prior neck radiation and surgery?', '["Tracheoesophageal fistula", "Carotid artery blowout syndrome", "Meningitis", "Retropharyngeal abscess", "Pulmonary embolism"]'::jsonb, 1, 'Carotid blowout syndrome is the catastrophic rupture of the carotid artery due to tumor invasion, infection, and tissue necrosis in a previously irradiated field. It is a terrifying emergency that is often fatal.'),
    (v_topic_id, 'A patient undergoes a total laryngectomy and bilateral neck dissections. The thoracic duct is inadvertently injured on the left side during the dissection of Level IV. What is the immediate intraoperative consequence?', '["Massive hemorrhage", "Pneumothorax", "Leakage of milky, chylous fluid into the neck wound", "Paralysis of the diaphragm", "Vocal cord paralysis"]'::jsonb, 2, 'The thoracic duct empties into the venous system at the junction of the left internal jugular and subclavian veins (Level IV). Injury results in a chyle leak, which appears as a steady flow of milky, lipid-rich fluid.'),
    (v_topic_id, 'If a small chyle leak is noticed postoperatively in the surgical drain, what is the initial medical management?', '["Immediate surgical re-exploration", "Administration of intravenous heparin", "Institution of a strict low-fat, medium-chain triglyceride (MCT) diet or taking the patient completely NPO with Total Parenteral Nutrition (TPN)", "Administration of broad-spectrum antibiotics", "Applying a tight pressure dressing to the neck"]'::jsonb, 2, 'Dietary modification is the first line of defense. Long-chain triglycerides require absorption through the thoracic duct, increasing chyle flow. MCTs are absorbed directly into the portal venous system, bypassing the thoracic duct and drastically reducing chyle output to allow the leak to heal.'),
    (v_topic_id, 'If a high-output chyle leak (>500 mL/day) persists despite strict dietary management and octreotide therapy, what is the next most appropriate intervention?', '["Wait an additional month", "Surgical re-exploration to identify and ligate the thoracic duct", "Radiation therapy to the lower neck", "Injection of sclerosing agents through the drain", "Placing a larger drain"]'::jsonb, 1, 'High-output leaks rapidly cause severe metabolic, nutritional, and immunologic depletion (due to the loss of fat, proteins, and lymphocytes). If medical management fails, surgical re-exploration and definitive ligation of the duct are mandatory.'),
    (v_topic_id, 'Which of the following describes the anatomical boundaries of Level I of the neck?', '["Between the hyoid bone and the cricoid cartilage", "Above the hyoid bone, bounded by the anterior belly of the digastric, the mandible, and the posterior belly of the digastric", "Between the sternocleidomastoid and the trapezius muscles", "Along the upper third of the internal jugular vein", "The central compartment between the carotid sheaths"]'::jsonb, 1, 'Level I contains the submental (Ia) and submandibular (Ib) triangles, bounded superiorly by the mandible and inferiorly by the digastric muscles and the hyoid bone.'),
    (v_topic_id, 'Level VI is the "central compartment" of the neck. Which of the following lymph node groups is located in Level VI?', '["Jugulodigastric nodes", "Spinal accessory nodes", "Supraclavicular nodes", "Paratracheal, pretracheal, and prelaryngeal (Delphian) nodes", "Submandibular nodes"]'::jsonb, 3, 'Level VI is bounded by the hyoid bone superiorly, the suprasternal notch inferiorly, and the carotid sheaths laterally. It is the primary drainage basin for the thyroid gland, subglottis, and cervical trachea.'),
    (v_topic_id, 'A patient presents with a palpable, hard "Delphian node." Where is this node located, and what primary malignancy does it strongly suggest?', '["In the supraclavicular fossa; suggests gastric cancer (Virchow''s node)", "Just anterior to the cricothyroid membrane; suggests laryngeal (subglottic) or thyroid cancer", "In the parotid gland; suggests cutaneous SCC", "Behind the ear; suggests scalp melanoma", "Under the chin; suggests lip cancer"]'::jsonb, 1, 'The Delphian node is a prelaryngeal lymph node located on the cricothyroid membrane. Its enlargement is a classic sign of advanced subglottic laryngeal cancer or anteriorly invasive thyroid cancer.'),
    (v_topic_id, 'A 60-year-old male with a history of heavy smoking and alcohol use presents with a painless, hard mass in the left supraclavicular fossa (Level IV/V). While a head and neck primary tumor is possible, what other highly likely source must be ruled out?', '["A primary brain tumor", "A malignancy below the clavicles, particularly lung, esophageal, or gastric carcinoma", "A primary bone tumor of the clavicle", "A benign thyroid nodule", "A parotid malignancy"]'::jsonb, 1, 'Supraclavicular lymphadenopathy (especially on the left, known as Virchow''s node) frequently represents metastasis from a distant primary tumor in the thorax or abdomen traveling via the thoracic duct.'),
    (v_topic_id, 'What is the most appropriate initial radiologic imaging modality for staging the neck in a patient newly diagnosed with a 3-cm squamous cell carcinoma of the oral tongue?', '["Plain soft tissue X-ray of the neck", "Contrast-enhanced CT scan or MRI of the neck", "Ultrasound of the neck without biopsy", "Bone scan", "Non-contrast CT of the brain"]'::jsonb, 1, 'Contrast-enhanced CT or MRI provides the necessary anatomical detail to evaluate for occult lymph node metastases, extranodal extension, and the tumor''s relationship to major blood vessels and the mandible.'),
    (v_topic_id, 'Radiographically, what finding on a contrast-enhanced CT scan of a cervical lymph node is highly specific for metastatic squamous cell carcinoma?', '["A perfectly round, homogenous node", "A node measuring exactly 9 mm", "A node with a central necrotic (cystic/hypodense) core and an enhancing rim", "A heavily calcified node", "A node that contains fat"]'::jsonb, 2, 'Central necrosis within a lymph node in a high-risk adult is a hallmark sign of metastatic squamous cell carcinoma. Even if the node is small (<1 cm), the presence of necrosis makes it radiologically positive.'),
    (v_topic_id, 'What is "extranodal extension" (ENE) or "extracapsular spread" in the context of metastatic lymph nodes, and why is it critical?', '["The tumor has spread to multiple nodes", "The tumor cells have breached the capsule of the lymph node and are invading the surrounding fat and soft tissue of the neck; it is a major adverse prognostic factor requiring postoperative chemoradiation", "The node has ruptured due to infection", "The tumor is benign", "The node is very large"]'::jsonb, 1, 'Extranodal extension signifies a highly aggressive tumor phenotype. It drastically increases the risk of local recurrence and distant metastasis. Its presence on surgical pathology is an absolute indication for adding concurrent chemotherapy to postoperative radiation.'),
    (v_topic_id, 'A patient undergoes a radical neck dissection. The pathology report notes that the tumor has encased and invaded the internal jugular vein. What must the surgeon do during the operation?', '["Peel the tumor off the vein", "Ligate and resect the internal jugular vein en bloc with the tumor", "Leave the tumor behind and use radiation", "Perform a vein bypass graft", "Prescribe blood thinners"]'::jsonb, 1, 'In a radical neck dissection, if the internal jugular vein is involved by the tumor, it is routinely ligated and resected to achieve clear margins. Unilateral IJV resection is generally well-tolerated without significant long-term consequence.'),
    (v_topic_id, 'If a patient requires a BILATERAL radical neck dissection involving the resection of BOTH internal jugular veins, what severe postoperative complication must the surgical team meticulously manage?', '["Bilateral vocal cord paralysis", "Massive facial and cerebral edema, potentially leading to increased intracranial pressure and blindness", "Inability to turn the head", "Severe hypocalcemia", "Bilateral shoulder syndrome"]'::jsonb, 1, 'Removing both primary venous drainage pathways of the brain simultaneously causes severe venous stasis. Patients develop massive head and facial swelling and are at risk for life-threatening cerebral edema. The dissections are often staged, or one IJV is reconstructed if possible.'),
    (v_topic_id, 'A 45-year-old male with a slowly growing midline neck mass undergoes excision. Pathology reveals it is a thyroglossal duct cyst. However, a 5-mm focus of malignancy is found incidentally within the cyst wall. What is the most common malignancy found in a thyroglossal duct cyst?', '["Squamous cell carcinoma", "Papillary thyroid carcinoma", "Medullary thyroid carcinoma", "Lymphoma", "Anaplastic thyroid carcinoma"]'::jsonb, 1, 'Because thyroglossal duct cysts contain ectopic thyroid tissue, they can occasionally harbor thyroid malignancies. Papillary thyroid carcinoma is by far the most common (about 80% of cases).'),
    (v_topic_id, 'A Sistrunk procedure is the standard surgical treatment for a thyroglossal duct cyst. What critical anatomical structure MUST be partially resected during this procedure to prevent a near 100% recurrence rate?', '["The thyroid gland", "The cricoid cartilage", "The central portion of the hyoid bone", "The sternocleidomastoid muscle", "The internal jugular vein"]'::jsonb, 2, 'The thyroglossal duct tract frequently passes through or intimately wraps around the hyoid bone during embryologic descent. The Sistrunk procedure involves removing the cyst, the entire tract up to the base of the tongue, and the central block of the hyoid bone.'),
    (v_topic_id, 'A 2-year-old child presents with a sudden onset of a rapidly enlarging, tender, erythematous mass in the lateral neck (Level II) following an upper respiratory infection. What is the most likely diagnosis?', '["Metastatic squamous cell carcinoma", "Infected branchial cleft cyst", "Cystic hygroma (lymphangioma)", "Thyroglossal duct cyst", "Hemangioma"]'::jsonb, 1, 'Branchial cleft cysts (most commonly second branchial cleft) often remain asymptomatic until they become acutely infected during an upper respiratory tract infection, presenting as a sudden, painful, swollen neck mass.'),
    (v_topic_id, 'A second branchial cleft cyst tract typically courses BETWEEN which two major vascular structures?', '["The internal and external carotid arteries", "The internal jugular vein and the common carotid artery", "The external jugular vein and the internal jugular vein", "The subclavian artery and vein", "The superior and inferior thyroid arteries"]'::jsonb, 0, 'The classic tract of a second branchial cleft anomaly passes deep to the platysma, ascends along the carotid sheath, passes BETWEEN the internal and external carotid arteries, and terminates in the tonsillar fossa.'),
    (v_topic_id, 'A newborn is noted to have a massive, soft, brilliantly transilluminating, painless mass in the posterior triangle of the neck. What is the most likely diagnosis?', '["Teratoma", "Cystic hygroma (lymphangioma)", "Thyroglossal duct cyst", "Branchial cleft cyst", "Neuroblastoma"]'::jsonb, 1, 'A cystic hygroma is a congenital malformation of the lymphatic system, presenting as a multilocular, highly cystic mass that brilliantly transilluminates light. It typically presents at birth or in early infancy.'),
    (v_topic_id, 'What is the primary, most life-threatening concern in a neonate presenting with a massive cystic hygroma of the neck?', '["Malignant transformation", "Severe infection", "Airway compromise due to compression or involvement of the larynx/trachea", "Rupture of the cyst", "Cosmetic deformity"]'::jsonb, 2, 'Massive lymphangiomas can infiltrate the soft tissues of the neck, floor of the mouth, and larynx, causing immediate and severe airway obstruction at birth, often necessitating an EXIT procedure (Ex Utero Intrapartum Treatment) or immediate tracheostomy.'),
    (v_topic_id, 'While surgical excision was traditionally the mainstay of treatment for cystic hygromas, what minimally invasive alternative is increasingly used as a primary or adjunct therapy, particularly for macroscopic cysts?', '["Radiation therapy", "Intralesional injection of sclerosing agents (e.g., OK-432, bleomycin, or doxycycline)", "Systemic chemotherapy", "High-dose oral steroids", "Laser ablation"]'::jsonb, 1, 'Sclerotherapy involves injecting an irritant directly into the cysts to cause intense inflammation, scarring, and obliteration of the lymphatic spaces, avoiding the nerve injuries associated with complex surgical excision.'),
    (v_topic_id, 'A 35-year-old pregnant woman presents with a rapidly growing, bleeding, friable mass on her gingiva (gums). It bleeds profusely when she brushes her teeth. What is the most likely diagnosis?', '["Squamous cell carcinoma", "Pyogenic granuloma (pregnancy tumor)", "Ameloblastoma", "Kaposi sarcoma", "Hemangioma"]'::jsonb, 1, 'A pyogenic granuloma (lobular capillary hemangioma) is a benign, rapidly growing, highly vascular lesion that frequently occurs on the gingiva of pregnant women due to hormonal changes. It is not a true granuloma, nor is it pyogenic (pus-producing).'),
    (v_topic_id, 'A 45-year-old male with HIV/AIDS presents with multiple asymptomatic, purple-red, violaceous macules and nodules on his hard palate and gingiva. What is the diagnosis and its causative agent?', '["Pyogenic granuloma; local trauma", "Squamous cell carcinoma; HPV", "Kaposi sarcoma; Human Herpesvirus 8 (HHV-8)", "Non-Hodgkin lymphoma; EBV", "Candidiasis; Candida albicans"]'::jsonb, 2, 'Kaposi sarcoma is a vascular tumor highly associated with HIV/AIDS and caused by infection with HHV-8. The hard palate is the most common site of intraoral involvement.'),
    (v_topic_id, 'A patient with a history of intravenous bisphosphonate therapy (e.g., zoledronic acid) for metastatic breast cancer undergoes a routine tooth extraction. Three months later, she presents with severe jaw pain and exposed, necrotic bone at the extraction site. What is the diagnosis?', '["Osteoradionecrosis", "Medication-Related Osteonecrosis of the Jaw (MRONJ)", "Squamous cell carcinoma of the alveolus", "Osteomyelitis", "Fibrous dysplasia"]'::jsonb, 1, 'MRONJ (formerly BRONJ) is a severe complication of antiresorptive drugs (bisphosphonates, denosumab). These drugs profoundly inhibit osteoclast function, preventing the bone remodeling necessary to heal from dental trauma, leading to exposed, necrotic bone.'),
    (v_topic_id, 'What is the primary cornerstone of management for early-stage Medication-Related Osteonecrosis of the Jaw (MRONJ) characterized by asymptomatic exposed bone without severe infection?', '["Immediate radical segmental mandibulectomy", "Aggressive surgical curettage to bleeding bone", "Conservative management with antimicrobial mouth rinses (e.g., chlorhexidine), oral antibiotics if superinfected, and avoiding further dental trauma", "Hyperbaric oxygen therapy", "Radiation therapy"]'::jsonb, 2, 'Unlike osteoradionecrosis, aggressive surgical debridement in MRONJ often exacerbates the condition by creating more surgical trauma that cannot heal. Conservative management is the mainstay until the bone sequestrum naturally separates.')
